using Microsoft.AspNetCore.Mvc;
using Race_Day_Part_3_MVC.Filters;
using Race_Day_Part_3_MVC.Services;
using System.Collections.Generic;
using System.Net.Http.Headers;
using System.Threading.Tasks;

namespace Race_Day_Part_3_MVC.Controllers
{
    // COMMENT OUT THIS LINE TEMPORARILY:
    // [MvcSessionAuthorize("Organiser")]
    public class OrganiserController : Controller
    {


        private readonly IApiService _apiService;

        public OrganiserController(IApiService apiService)
        {
            _apiService = apiService;
        }

        // Requirement 3: Dashboard summarizing event counters
        public async Task<IActionResult> Dashboard()
        {
            var token = HttpContext.Session.GetString("JwtToken");
            var metrics = await _apiService.GetFromJsonAsync<Dictionary<string, int>>("organiser/metrics", token);
            return View(metrics ?? new Dictionary<string, int> { { "TotalEvents", 0 }, { "TotalEnrolments", 0 } });
        }

        [HttpGet]
        public IActionResult CreateEvent() => View();

        // Requirements 3 & 5: Event creation combined with Azure Blob image uploads via API forwarding
        [HttpPost]
        public async Task<IActionResult> CreateEvent(string name, string description, string date, string location, double distance, string eventType, IFormFile bannerImage)
        {
            var token = HttpContext.Session.GetString("JwtToken");
            using var multipartContent = new MultipartFormDataContent();

            multipartContent.Add(new StringContent(name), "Name");
            multipartContent.Add(new StringContent(description), "Description");
            multipartContent.Add(new StringContent(date), "Date");
            multipartContent.Add(new StringContent(location), "Location");
            multipartContent.Add(new StringContent(distance.ToString()), "Distance");
            multipartContent.Add(new StringContent(eventType), "EventType");

            if (bannerImage != null && bannerImage.Length > 0)
            {
                var fileStreamContent = new StreamContent(bannerImage.OpenReadStream());
                fileStreamContent.Headers.ContentType = new MediaTypeHeaderValue(bannerImage.ContentType);
                multipartContent.Add(fileStreamContent, "BannerImage", bannerImage.FileName);
            }

            // All file handling goes through the Part 2 API to Azure Storage
            var response = await _apiService.PostMultipartAsync("events", multipartContent, token);
            if (response.IsSuccessStatusCode) return RedirectToAction("Dashboard");

            ModelState.AddModelError("", "Failed to submit event profile tracking metadata to system backend.");
            return View();
        }
    }
}

